function fixUsinaLigada(value) {
  if (isNaN(Date.parse(value)) == true) {
    return { status: "NÃO REALIZADO", data: null };
  } else {
    return { status: "REALIZADO", data: new Date(value) };
  }
}
function fixDate(value) {
  if (isNaN(Date.parse(value)) == true) {
    return null;
  } else {
    return new Date(value).toISOString();
  }
}
